#!/usr/bin/env node

/**
 * Post-build script to fix the remoteEntry.js generated by @originjs/vite-plugin-federation
 * 
 * Issue: When using a base path with Module Federation, the generated CSS loader
 * has a stray 'assets' string literal that breaks CSS loading in some circumstances.
 * 
 * This script:
 * 1. Removes the stray 'assets' string literal
 * 2. Ensures CSS paths include the 'assets/' directory
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const remoteEntryPath = path.join(__dirname, '../dist/assets/remoteEntry.js');

if (!fs.existsSync(remoteEntryPath)) {
  console.error(`Error: remoteEntry.js not found at ${remoteEntryPath}`);
  console.error('Make sure to run: yarn build');
  process.exit(1);
}

let content = fs.readFileSync(remoteEntryPath, 'utf-8');

// Remove the stray 'assets' string literal that appears before the cssFilePaths.forEach
// This can appear in several forms depending on whether the code is minified or not:
// 1. Unminified: `const base = '...'; 'assets'; cssFilePaths.forEach`
// 2. Minified: `o='/scp-mfe/';'assets',e.forEach` or similar
// 3. Minified with backticks: `o='/scp-mfe/';'assets',` followed by variable.forEach

// Pattern for unminified code
content = content.replace(/;\s*'assets';\s*cssFilePaths\.forEach/g, ';\n\tcssFilePaths.forEach');

// Pattern for minified code: 'assets', followed by variable.forEach
content = content.replace(/'assets',(\w+)\.forEach/g, '$1.forEach');

// Also handle backtick versions in case they exist
content = content.replace(/;'assets',/g, ',');
content = content.replace(/;`assets`,/g, ',');

fs.writeFileSync(remoteEntryPath, content, 'utf-8');
console.log('✓ Fixed remoteEntry.js: removed stray "assets" string literal');
